'use strict';

// Reads a.txt, b.txt, c.txt, cross-checks each parsed population against the
// raw line, computes the sum, and writes answer.json with a numeric total.

const fs = require('fs');
const path = require('path');

const sources = [
  { file: 'a.txt', expectedName: 'Alpha' },
  { file: 'b.txt', expectedName: 'Beta' },
  { file: 'c.txt', expectedName: 'Gamma' },
];

const parsed = [];

for (const src of sources) {
  const full = path.join(__dirname, src.file);
  const raw = fs.readFileSync(full, 'utf8');
  const lines = raw.split(/\r?\n/).filter((l) => l.trim() !== '');

  if (lines.length !== 1) {
    throw new Error(`${src.file}: expected exactly 1 non-empty line, got ${lines.length}`);
  }

  const match = lines[0].match(/^([A-Za-z]+) population:\s*(\d+)\s*$/);
  if (!match) {
    throw new Error(`${src.file}: line does not match "<Name> population: <int>": ${JSON.stringify(lines[0])}`);
  }

  const name = match[1];
  const value = Number(match[2]);

  // Cross-check: name matches the expected label for this file, and the parsed
  // value round-trips to the exact digit string found on disk.
  if (name !== src.expectedName) {
    throw new Error(`${src.file}: expected label ${src.expectedName}, got ${name}`);
  }
  if (String(value) !== match[2]) {
    throw new Error(`${src.file}: value ${match[2]} did not parse losslessly`);
  }
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new Error(`${src.file}: value ${match[2]} is not a safe non-negative integer`);
  }

  parsed.push({ file: src.file, name, value });
}

const total = parsed.reduce((acc, p) => acc + p.value, 0);

const out = path.join(__dirname, 'answer.json');
fs.writeFileSync(out, JSON.stringify({ total }, null, 2) + '\n', 'utf8');

for (const p of parsed) {
  console.log(`cross-check ok: ${p.file} -> ${p.name} population ${p.value}`);
}
console.log(`total = ${total}`);
console.log(`wrote ${out}`);

'use strict';

// Independent check of answer.json: recomputes the total from the raw sources
// using a different route than compute.js and asserts the JSON contract.

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// Route 2: pull every integer out of each raw file and compare per-file.
const expected = { 'a.txt': 12, 'b.txt': 18, 'c.txt': 30 };
let recomputed = 0;

for (const [file, value] of Object.entries(expected)) {
  const raw = fs.readFileSync(path.join(__dirname, file), 'utf8');
  const nums = raw.match(/\d+/g);
  assert.ok(nums && nums.length === 1, `${file}: expected one integer, got ${JSON.stringify(nums)}`);
  assert.strictEqual(Number(nums[0]), value, `${file}: expected ${value}, raw text has ${nums[0]}`);
  recomputed += value;
}

const outPath = path.join(__dirname, 'answer.json');
const outRaw = fs.readFileSync(outPath, 'utf8');
const answer = JSON.parse(outRaw);

assert.strictEqual(typeof answer, 'object' && answer !== null, 'answer.json must be an object');
assert.ok('total' in answer, 'answer.json must contain key "total"');
assert.strictEqual(typeof answer.total, 'number', `total must be numeric, got ${typeof answer.total}`);
assert.ok(Number.isSafeInteger(answer.total), 'total must be a safe integer');
assert.strictEqual(answer.total, 60, `total must equal 60, got ${answer.total}`);
assert.strictEqual(answer.total, recomputed, `total must equal independently recomputed sum ${recomputed}`);
assert.deepStrictEqual(Object.keys(answer), ['total'], `unexpected extra keys: ${Object.keys(answer)}`);

console.log('PASS: each source population confirmed (a.txt=12, b.txt=18, c.txt=30)');
console.log(`PASS: answer.json total is numeric and equals ${answer.total}`);
console.log(`PASS: total matches independent recomputation (${recomputed})`);
console.log(`PASS: answer.json keys = ${JSON.stringify(Object.keys(answer))}`);

