node -e '
const fs=require("fs");
const files=["a.txt","b.txt","c.txt"];
let sum=0; const rows=[];
for(const f of files){
  const raw=fs.readFileSync(f,"utf8");
  const m=raw.match(/^([A-Za-z]+)\s+population\s*:\s*(\d+)\s*$/m);
  if(!m) throw new Error("cannot parse "+f+": "+JSON.stringify(raw));
  const v=parseInt(m[2],10);
  if(!Number.isSafeInteger(v)) throw new Error("bad int in "+f);
  rows.push([f,m[1],v]); sum+=v;
}
const ans=JSON.parse(fs.readFileSync("answer.json","utf8"));
const keys=Object.keys(ans);
const okObj = ans && typeof ans==="object" && !Array.isArray(ans);
const okKey = keys.length===1 && keys[0]==="total";
const okNum = typeof ans.total==="number" && Number.isFinite(ans.total);
console.log("parsed:", JSON.stringify(rows));
console.log("node sum =", sum, "| typeof sum:", typeof sum);
console.log("answer =", JSON.stringify(ans), "| keys:", JSON.stringify(keys));
console.log("object:", okObj, "| single total key:", okKey, "| numeric:", okNum);
console.log("total===sum:", ans.total===sum);
if(!okObj||!okKey||!okNum||ans.total!==sum){ console.error("FAIL"); process.exit(1); }
console.log("INDEPENDENT VERIFY PASS");
' ; echo "exit=$?"
